from dataclasses import dataclass
@dataclass
class Course:
    code: str
    credits: int = 3


def main():
    print(Course("CSE212").credits)


if __name__ == "__main__":
    main()

from dataclasses import dataclass, field
@dataclass
class Bag:
    values: list[int] = field(default_factory=list)


def main():
    a, b = Bag(), Bag()
    a.values.append(1)
    print(a.values, b.values)


if __name__ == "__main__":
    main()

from dataclasses import dataclass
@dataclass
class Point:
    x: int


def main():
    a, b = Point(2), Point(2)
    print(a == b, a is b)


if __name__ == "__main__":
    main()
